def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    aggressive_bids = []
    moderate_bids = []

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)
                if bid >= 60:
                    aggressive_bids.append(bid)
                else:
                    moderate_bids.append(bid)

    if budget <= 0:
        return 0.0

    if not alive_opps:
        return float(min(budget, 20.0))

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2

    if no_water >= 2:
        urgency += 4
    elif no_water >= 1:
        urgency += 2

    if supply <= 17:
        urgency += 3
    elif supply <= 20:
        urgency += 1

    if day >= 8:
        urgency += 1

    moderate_anchor = 33.0
    if moderate_bids:
        moderate_anchor = max(moderate_bids)
    elif prev_bids:
        moderate_anchor = min(prev_bids)

    high_anchor = 62.0
    if aggressive_bids:
        high_anchor = max(aggressive_bids)
    elif prev_bids:
        high_anchor = max(prev_bids)

    alive_count = len(alive_opps)

    if urgency >= 7:
        bid = max(0.92 * DAILY_SALARY, moderate_anchor + 2.5)
        if supply <= 17:
            bid = max(bid, min(high_anchor + 1.0, budget))
    elif urgency >= 4:
        if supply <= 17:
            bid = max(0.78 * DAILY_SALARY, moderate_anchor + 2.0)
        else:
            bid = max(0.58 * DAILY_SALARY, moderate_anchor + 1.5)
    else:
        if supply >= 22:
            bid = 0.22 * DAILY_SALARY
        elif supply >= 19:
            bid = 0.34 * DAILY_SALARY
        else:
            bid = 0.46 * DAILY_SALARY

    if alive_count >= 3 and supply <= 17 and hp > 4 and no_water == 0:
        bid = min(bid, 0.52 * DAILY_SALARY)

    reserve = 0.0
    days_left = max(0, 10 - day)
    if days_left > 0:
        reserve = min(budget * 0.35, days_left * 18.0)

    cap = budget - reserve
    if urgency >= 7:
        cap = budget
    elif urgency >= 4:
        cap = max(cap, budget * 0.7)
    else:
        cap = max(cap, budget * 0.45)

    bid = min(bid, cap, budget)

    if hp <= 2 or no_water >= 2:
        bid = max(bid, min(budget, 65.0))

    if bid < 0:
        bid = 0.0

    return float(round(min(bid, budget), 2))

