def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Rule 1: If no opponents are alive, bid minimally to get water and save budget.
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Rule 2: If HP is critically low, bid very aggressively to ensure survival.
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # Collect yesterday's bids from all active opponents.
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Rule 3: React to opponents' previous bidding behavior.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # Scenario A: Opponents were bidding very high (fierce competition).
        if highest_prev_bid >= DAILY_SALARY * 0.85: # e.g., 119 for a 140 salary
            if my_status['hp'] > 5: # My HP is good, can afford to be slightly less aggressive or try to save.
                # Bid competitively, slightly above previous high, but not maxing out.
                return min(my_status['budget'], max(DAILY_SALARY * 0.6, highest_prev_bid + 2.0))
            else: # My HP is moderate to low, need water more urgently.
                return min(my_status['budget'], DAILY_SALARY * 0.9) # Be aggressive.

        # Scenario B: Opponents were bidding moderately or low.
        else: # highest_prev_bid < DAILY_SALARY * 0.85
            if my_status['hp'] > 5: # My HP is good, can afford to save budget while securing water.
                # Bid slightly above the highest previous bid, but keep it reasonable.
                return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))
            else: # My HP is moderate to low, be more aggressive to secure water.
                return min(my_status['budget'], max(DAILY_SALARY * 0.7, highest_prev_bid + 2.5))

    # Rule 4: Fallback strategy if no previous bids are available (e.g., Day 1).
    # This ensures a bid is always returned.
    if my_status['hp'] <= 4: # If HP is somewhat low, bid higher.
        return min(my_status['budget'], DAILY_SALARY * 0.75)
    else: # HP is good, bid moderately.
        return min(my_status['budget'], DAILY_SALARY * 0.6)
